    if(!film){if(!catalogProject){catalogProject={id:LIST_CATALOG_PROJECT_ID,name:"Sammlungen & Playlists",description:"Automatisch angelegte Film- und Serieneinträge aus Sammlungen und Playlists.",createdAt:new Date().toISOString(),films:[]};projects.push(catalogProject)}const mediaType=placeholder.mediaType==="tv"?"tv":"movie";film={id:uid("film"),mediaType,title:placeholder.title||placeholder.originalTitle||"Unbekannter Titel",originalTitle:placeholder.originalTitle||placeholder.title||"",year:Number(String(placeholder.year||"").match(/\d{4}/)?.[0])||"",cover:placeholder.cover||"",originalCover:placeholder.cover||"",copies:[],status:"nicht verfügbar",catalogEntry:true};FILM_IDENTIFIER_KEYS.forEach(key=>{const value=playlistIdentifierValue(placeholder,key);if(value)film[key]=String(value)});catalogProject.films.push(film);registerFilm(film);created++;changed=true}
