function catalogDiscoveryFilms(){const selected=selectedCatalogProjectIds.size?projects.filter(project=>selectedCatalogProjectIds.has(String(project.id))):projects,seen=new Set();return selected.flatMap(project=>project.films).filter(film=>{const id=String(film.id);if(seen.has(id)||!filmHasAvailableCopy(film))return false;seen.add(id);return true})}
