function filmCollectionNumber(film){const relevant=catalogPlaylistId==="all"?playlists:playlists.filter(playlist=>sameId(playlist.id,catalogPlaylistId));for(const playlist of relevant){const assigned=playlistNumber(playlist,film.id);if(assigned)return assigned;const entry=(playlist.placeholders||[]).find(item=>sameId(item.filmId,film.id));if(entry?.collectionNumber)return String(entry.collectionNumber)}return ""}
function normalizedFranchise(value){return String(value||"").replace(/^\s*#+\s*/,"").trim()}
