function isNeonTheme(){return document.documentElement.dataset.theme==="neon"}
let neonHeaderFrame;
const touchHeaderMotionQuery=window.matchMedia("(max-width: 1180px), (pointer: coarse)");
function syncNeonHeader(){cancelAnimationFrame(neonHeaderFrame);neonHeaderFrame=requestAnimationFrame(()=>{const root=document.documentElement,active=currentView==="cinema"&&isNeonTheme(),mobile=window.innerWidth<=800,touchMotion=touchHeaderMotionQuery.matches,wasCollapsed=root.dataset.headerCollapsed==="true",scroll=Math.max(window.scrollY,0);let progress;if(touchMotion){root.dataset.touchHeaderMotion="true";const collapseAt=mobile?64:88,expandAt=mobile?26:38,collapsed=active&&(wasCollapsed?scroll>expandAt:scroll>=collapseAt),state=`${collapsed?1:0}:${mobile?"mobile":"tablet"}`;progress=collapsed?1:0;if(root.dataset.touchHeaderState===state)return;root.dataset.touchHeaderState=state}else{delete root.dataset.touchHeaderMotion;delete root.dataset.touchHeaderState;progress=active?Math.min(scroll/360,1):0}const maxShrink=mobile?172:239,fade=Math.min(Math.max((progress-.48)/.3,0),1);root.style.setProperty("--neon-header-shrink",`${(progress*maxShrink).toFixed(2)}px`);root.style.setProperty("--neon-header-offset",`${(-progress*(mobile?150:230)).toFixed(2)}px`);root.style.setProperty("--neon-header-scale",(1-progress*.42).toFixed(3));root.style.setProperty("--neon-header-brand-opacity",(1-fade).toFixed(3));if(active&&progress>=.995)root.dataset.headerCollapsed="true";else delete root.dataset.headerCollapsed})}
