function filteredFilms(){const films=catalogFilms().filter(f=>{const year=catalogYearValue(String(f.year||"").match(/\d{4}/)?.[0]),matchesYear=(!catalogYearFrom&&!catalogYearTo)||(year!==null&&(!catalogYearFrom||year>=catalogYearFrom)&&(!catalogYearTo||year<=catalogYearTo));return filmMatchesGenre(f)&&matchesYear&&((selectedCatalogLanguages.size===0&&selectedCatalogSubtitles.size===0)||filmLanguages(f).some(language=>selectedCatalogLanguages.has(language.key))||filmSubtitles(f).some(subtitle=>selectedCatalogSubtitles.has(subtitle.key)))&&filmMatchesQuery(f,catalogSearchQuery)});const collator=new Intl.Collator(interfaceLanguage(),{sensitivity:"base",numeric:true}),byTitle=(a,b)=>collator.compare(String(a.title||""),String(b.title||"")),byCollectionNumber=(a,b)=>{const aNumber=filmCollectionNumber(a),bNumber=filmCollectionNumber(b);if(!aNumber)return bNumber?1:byTitle(a,b);if(!bNumber)return -1;return collator.compare(aNumber,bNumber)||byTitle(a,b)},randomValue=film=>{const id=String(film.id);if(!catalogRandomOrder.has(id))catalogRandomOrder.set(id,Math.random());return catalogRandomOrder.get(id)};return films.sort((a,b)=>catalogSort==="random"?randomValue(a)-randomValue(b):catalogSort==="collection-number"?byCollectionNumber(a,b):catalogSort==="year-desc"?(Number(b.year)||0)-(Number(a.year)||0)||byTitle(a,b):catalogSort==="year-asc"?(Number(a.year)||9999)-(Number(b.year)||9999)||byTitle(a,b):catalogSort==="genre"?collator.compare(genreText(a.genre),genreText(b.genre))||byTitle(a,b):byTitle(a,b))}
