let openFilmCopyIds=new Set(),knownFilmCopyIds=new Set(),copyEditorFilmId="";
function copyEditorHeading(row,index){const physical=row.querySelector('[data-copy-field="storageType"]')?.value==="physical",source=row.querySelector('[data-copy-field="title"]')?.value.trim(),medium=row.querySelector('[data-copy-field="medium"]')?.value.trim(),edition=row.querySelector('[data-copy-field="edition"]')?.value.trim(),languages=row.querySelector('[data-copy-field="languages"]')?.value.trim(),resolution=row.querySelector('[data-copy-field="resolution"]')?.value.trim(),primary=physical?(medium||"Physische Fassung"):(source||"Digitale Fassung"),parts=[primary];if(languages)parts.push(languages);if(physical&&edition)parts.push(edition);if(!physical&&resolution)parts.push(resolution);return parts.filter(Boolean).join(" · ")||`Fassung ${index+1}`}
