function updateSubtitleSyncCue(){const state=subtitleSyncState;if(!state)return;const cue=state.cues[state.cueIndex],track=editingSubtitleTracks.find(item=>sameId(item.id,state.trackId)),copy=editingCopies.find(item=>sameId(item.id,state.copyId)),offset=cueOffsetFor(track,copy,state.cueIndex,state.edits);state.offset=offset;$("subtitleSyncCueNumber").textContent=`${state.cueIndex+1} / ${state.cues.length}`;$("subtitleSyncCueText").textContent=cue?.text||"(Leerer Untertitel)";$("subtitleSyncCueTime").textContent=formatSubtitleTime(cue?.start||0);$("subtitleSyncCorrectedTime").value=formatSubtitleTime(Math.max(0,(cue?.start||0)+offset));$("subtitleSyncOffset").textContent=formatSubtitleTime(offset,true);$("subtitleSyncSave").disabled=!state.changed}
function autoUpdateSubtitleSync(positionMs){const state=subtitleSyncState;if(!state||!$("subtitleSyncAutoUpdate").checked||!state.cues.length)return;const track=editingSubtitleTracks.find(item=>sameId(item.id,state.trackId)),copy=editingCopies.find(item=>sameId(item.id,state.copyId));let active=0,activeTime=-Infinity;state.cues.forEach((cue,index)=>{const corrected=cue.start+cueOffsetFor(track,copy,index,state.edits);if(corrected<=positionMs&&corrected>=activeTime){active=index;activeTime=corrected}});if(active!==state.cueIndex){state.cueIndex=active;updateSubtitleSyncCue()}}
function clearSubtitleSyncPreview(){const video=$("subtitleSyncVideo"),preview=video.querySelector("track[data-sync-preview]");if(preview){if(preview.track)preview.track.mode="disabled";preview.remove()}if(subtitleSyncState?.previewUrl){URL.revokeObjectURL(subtitleSyncState.previewUrl);subtitleSyncState.previewUrl=""}}
