function openSubtitleSync(trackId){readCopyEditor();readSubtitleEditor();const track=editingSubtitleTracks.find(item=>sameId(item.id,trackId)),cues=parseSubtitleCues(track);if(!track?.content||!cues.length){toast("Die Untertiteldatei enthält keine lesbaren Zeitmarken");return}const eligible=editingCopies.filter(copy=>!copy.storageType||copy.storageType==="digital");if(!eligible.length){toast("Lege zuerst eine digitale Filmfassung an");return}const preferred=eligible.find(copy=>sameId(copy.id,track.copyId))||eligible[0];subtitleSyncState={trackId:track.id,cues,cueIndex:0,copyId:preferred.id,edits:normalizedCueEdits(track,preferred),offset:0,changed:false,previewUrl:""};$("subtitleSyncTitle").textContent=track.label||track.fileName||"Zeitversatz festlegen";$("subtitleSyncCopy").innerHTML=syncCopyOptions(preferred.id);$("subtitleSyncWorkspace").hidden=true;$("subtitleSyncPreview").checked=false;$("subtitleSyncAutoUpdate").checked=true;$("subtitleSyncFollowCue").checked=true;$("subtitleSyncFollowing").checked=false;$("subtitleSyncStatus").textContent="Wähle die Filmfassung, deren Zeitablauf zu diesem Untertitel passen soll.";$("subtitleSyncSave").disabled=true;$("subtitleSyncVideo").removeAttribute("src");$("subtitleSyncDialog").showModal();updateSubtitleSyncCue()}
