const BONUS_CATEGORIES=[['trailer','Trailer'],['commentary','Kommentare'],['review','Rezensionen'],['deleted-scenes','Entfallene Szenen / Cut Scenes'],['making-of','Making-of'],['interview','Interviews'],['featurette','Featurettes'],['behind-the-scenes','Hinter den Kulissen'],['alternate-version','Alternative Fassungen'],['music','Musik & Soundtrack'],['gallery','Bilder & Galerien'],['promo','Werbung & Promotion'],['other','Weitere Extras']];
function bonusCategory(item={}){const stored=String(item.category||item.type||"").trim();if(BONUS_CATEGORIES.some(([value])=>value===stored))return stored;return /trailer/i.test(String(item.title||""))?"trailer":"other"}
