function readBonusEditor(){editingBonusMaterials=[...$("filmBonusList").querySelectorAll("[data-bonus-id]")].map(row=>({id:row.dataset.bonusId,title:row.querySelector('[data-bonus-field="title"]').value.trim(),category:row.querySelector('[data-bonus-field="category"]').value,link:row.querySelector('[data-bonus-field="link"]').value.trim(),languages:semanticLanguages(row.querySelector('[data-bonus-field="languages"]').value)})).filter(item=>item.title||item.link||item.languages.length)}
