async function initializeApplication(){
  document.documentElement.dataset.view=currentView;
  initializeTheme();
  initializeTmdbToken();
  if(window.NeonVStorage)try{
    const stored=await window.NeonVStorage.initialize({projects,playlists,settings:indexedStorageSettings()});
    const localRevision=stateRevision,indexedRevision=Number(stored.settings?.stateRevision)||0,localStateIsNewer=localSnapshotIsComplete()&&localRevision>indexedRevision;
    if(String(stored.source).startsWith("indexedDB")&&!localStateIsNewer){
      projects=stored.projects.length?stored.projects:projects;
      playlists=stored.playlists.length?stored.playlists:playlists;
      stateRevision=indexedRevision;
      projects.forEach(project=>(project.films||[]).forEach(film=>{if(!film.globalWorkId&&film.catalogWorkId)film.globalWorkId=film.catalogWorkId;delete film.catalogWorkId}));
      activeProjectId=projects.some(project=>sameId(project.id,stored.settings?.activeProjectId))?String(stored.settings.activeProjectId):projects[0]?.id||activeProjectId;
      activePlaylistId=playlists.some(playlist=>sameId(playlist.id,stored.settings?.activePlaylistId))?String(stored.settings.activePlaylistId):playlists[0]?.id||activePlaylistId;
    }
  }catch(error){console.warn("Neon V IndexedDB initialization failed; localStorage remains active",error)}
  const normalizedListKinds=normalizeListKinds(),installedImdbTop250=installImdbTop250Data(),installedLetterboxdTop500=installLetterboxdTop500Data(),installedSightSound2022=installSightSound2022Data(),installedAfricanCinemaCanon=installAfricanCinemaCanonData(),installedAfricanFilmHeritage=installAfricanFilmHeritageData(),installedOscarBestPicture=installOscarBestPictureData(),installedBfiSilentFilms=installBfiSilentFilmsData(),installedSightSoundDocumentaries=installSightSoundDocumentariesData(),migratedSeriesStructures=migrateSeriesStructures(),migratedTrailers=migrateTrailersToBonusMaterials();
  const installedCuratedCollection=installedImdbTop250||installedLetterboxdTop500||installedSightSound2022||installedAfricanCinemaCanon||installedAfricanFilmHeritage||installedOscarBestPicture||installedBfiSilentFilms||installedSightSoundDocumentaries,materializedPlaylistEntries=materializePlaylistEntries();
  if(installedCuratedCollection||materializedPlaylistEntries){reconcileAllPlaylistPlaceholders();syncPlaylistCollectionNumbers()}
  if(installedCuratedCollection||materializedPlaylistEntries||migratedSeriesStructures||migratedTrailers){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(projects));localStorage.setItem(PLAYLISTS_KEY,JSON.stringify(playlists))}catch{}persistIndexedState()}
  registerWebMCP();
  els.searchInput.value=catalogSearchQuery;
  render(false);
  projects.filter(project=>project.reconciliationPending).forEach(project=>queueProjectReconciliation(project.id));
  setArchiveSection(activeArchiveSection);
  translateUi();
  if(document.documentElement.lang==="en")new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===Node.ELEMENT_NODE)translateUi(node)}))).observe(document.body,{childList:true,subtree:true});
  delete document.documentElement.dataset.storageLoading;
  els.cinemaView.classList.add("is-view-loading");
  els.cinemaView.setAttribute("aria-busy","true");
  requestAnimationFrame(()=>setTimeout(renderCatalog,0));
  const maintainCatalog=()=>{const reconciledFilmDuplicates=reconcileDuplicateFilmsGlobally(),repairedTitles=repairMissingFilmTitles(),reconciledPlaylists=reconcileAllPlaylistPlaceholders();syncPlaylistCollectionNumbers();if(normalizedListKinds||reconciledFilmDuplicates||repairedTitles||reconciledPlaylists){try{localStorage.setItem(PLAYLISTS_KEY,JSON.stringify(playlists));if(reconciledFilmDuplicates||repairedTitles)localStorage.setItem(STORAGE_KEY,JSON.stringify(projects))}catch{}persistIndexedState();render()}if(reconciledFilmDuplicates)toast(reconciledFilmDuplicates===1?"Eine Dublette anhand übereinstimmender IDs zusammengeführt":`${reconciledFilmDuplicates} Dubletten anhand übereinstimmender IDs zusammengeführt`)};
  const maintenanceKey="videothek-catalog-maintenance-v1",maintenanceVersion="2026-09-26-2";
  if(localStorage.getItem(maintenanceKey)!==maintenanceVersion){const runMaintenance=()=>{if(projects.some(project=>project.reconciliationPending)){setTimeout(runMaintenance,5000);return}maintainCatalog();localStorage.setItem(maintenanceKey,maintenanceVersion)};if("requestIdleCallback" in window)requestIdleCallback(runMaintenance,{timeout:10000});else setTimeout(runMaintenance,4000)}
}
